def compute(vars):
    purchase_price = vars["Purchase Price"]
    net_fair_value_identifiable_net_assets = vars["Net Fair Value of Identifiable Net Assets"]
    goodwill = purchase_price - net_fair_value_identifiable_net_assets

    return {
        "value": goodwill,
        "trace": {
            "Purchase Price": purchase_price,
            "Net Fair Value of Identifiable Net Assets": net_fair_value_identifiable_net_assets,
            "output_meta": {
                "currency": None,
                "scale": "millions",
                "unit": None
            }
        }
    }
